// Shared pairing fixtures (NP-1114-36): the JS implementation asserts
// against the same fixture file the Go port asserts against
// (shared/testvectors/pairing-v1.json, generated by
// tools/gen-pairing-fixtures.mjs from THIS implementation). If the
// grammar ever changes, the fixture regenerates and both sides move.
import test from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { buildLink, buildExportObject, parseAnyPayload, previewOf } from "../src/pairing.js";
import { verifierHex } from "../src/config.js";

const F = JSON.parse(fs.readFileSync(path.join(path.dirname(fileURLToPath(import.meta.url)), "..", "..", "shared", "testvectors", "pairing-v1.json"), "utf8"));
const un = (h) => (h ? new Uint8Array(Buffer.from(h, "hex")) : null);
const shape = (p) => ({
  workerUrl: p.workerUrl, keyId: p.keyId,
  pskHex: p.psk ? Buffer.from(p.psk).toString("hex") : null,
  metaPath: p.metaPath, edgesPath: p.edgesPath,
});
const toInput = (i) => ({ workerUrl: i.workerUrl, keyId: i.keyId ?? undefined, psk: un(i.pskHex), metaPath: i.metaPath, edgesPath: i.edgesPath });

test("fixtures: builds match the canonical builders", () => {
  for (const b of F.builds) {
    assert.equal(buildLink(toInput(b.input)), b.link, b.name);
    assert.equal(JSON.stringify(buildExportObject(toInput(b.input))), b.exportJson, b.name);
  }
});
test("fixtures: parses produce the recorded shapes", () => {
  for (const p of F.parses) assert.deepEqual(shape(parseAnyPayload(p.text)), p.ok, p.name);
});
test("fixtures: error cases fail with the recorded messages", () => {
  for (const e of F.errors) assert.throws(() => parseAnyPayload(e.text), new RegExp(e.error.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")), e.name);
});
test("fixtures: previews match", () => {
  const parsed = parseAnyPayload(F.builds[1].link);
  for (const pv of F.previews) {
    assert.deepEqual(previewOf(parsed, { currentPskExists: pv.currentPskExists, verifierOf: verifierHex }), pv.preview);
  }
});
